css:
:scope { width: min(100%, 875px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i2 { grid-column: 1 / span 24; grid-row: 5 / span 15; font-family: var(--os-font-heading); font-size: 53.2px; font-weight: 700; line-height: 1.08; letter-spacing: -0.015em; color: var(--os-color-heading); }
.gx__i3 { grid-column: 1 / span 20; grid-row: 23 / span 4; font-family: var(--os-font-body); font-size: 24.9px; font-weight: 400; line-height: 1.38; letter-spacing: 0em; font-style: italic; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 10; grid-row: 41 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i5 { grid-column: 14 / span 10; grid-row: 41 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-link); }
.gx__i6 { grid-column: 1 / span 10; grid-row: 44 / span 5; font-family: var(--os-font-heading); font-size: 31.1px; font-weight: 700; line-height: 1.25; letter-spacing: -0.025em; color: var(--os-color-heading); }
.gx__i7 { grid-column: 14 / span 10; grid-row: 44 / span 5; font-family: var(--os-font-heading); font-size: 31.1px; font-weight: 700; line-height: 1.25; letter-spacing: -0.025em; color: var(--os-color-heading); }
.gx__i8 { grid-column: 1 / span 10; grid-row: 51 / span 16; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.62; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i9 { grid-column: 14 / span 10; grid-row: 51 / span 12; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.62; letter-spacing: 0em; color: var(--os-color-text); }
