.gx__i11 { grid-column: 1 / span 6; grid-row: 70 / span 2; font-family: var(--os-font-label); font-size: 12.8px; font-weight: 700; line-height: 1.33; letter-spacing: 0.18em; text-transform: uppercase; color: var(--os-color-link); }
