.gx__i13 { grid-column: 14 / span 10; grid-row: 87 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; color: var(--os-color-text-muted); }
.gx__i14 { grid-column: 1 / span 10; grid-row: 91 / span 10; font-family: var(--os-font-heading); font-size: 31.1px; font-weight: 700; line-height: 1.25; letter-spacing: -0.025em; color: var(--os-color-heading); }
.gx__i15 { grid-column: 14 / span 10; grid-row: 91 / span 10; font-family: var(--os-font-heading); font-size: 31.1px; font-weight: 700; line-height: 1.25; letter-spacing: -0.025em; color: var(--os-color-heading); }
.gx__i16 { grid-column: 1 / span 10; grid-row: 102 / span 20; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.62; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i17 { grid-column: 14 / span 10; grid-row: 102 / span 12; font-family: var(--os-font-body); font-size: 19.7px; font-weight: 400; line-height: 1.62; letter-spacing: 0em; color: var(--os-color-text); }
.gx__i18 { grid-column: 14 / span 3; grid-row: 117 / span 2; font-family: var(--os-font-label); font-size: 12.8px; font-weight: 700; line-height: 1.33; letter-spacing: 0.18em; text-transform: uppercase; color: var(--os-color-text-muted); }
.gx__i19 { grid-column: 1 / span 6; grid-row: 125 / span 2; font-family: var(--os-font-label); font-size: 12.8px; font-weight: 700; line-height: 1.33; letter-spacing: 0.18em; text-transform: uppercase; color: var(--os-color-text-muted); }
