  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 43px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 20px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i6 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i7 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i8 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i9 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i10 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i11 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i12 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i13 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i14 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i15 { font-family: var(--os-font-heading); font-size: 25px; }
  .gx__i16 { font-family: var(--os-font-body); font-size: 16px; }
